frontendCompletion.exactPowerShellCommand:
$ErrorActionPreference='Stop'
$script=@'
import fs from 'node:fs';
import { resolve } from 'node:path';
import { spawnSync } from 'node:child_process';
import { build } from 'vite';
import react from '@vitejs/plugin-react';
const startedAt = new Date().toISOString();
const outDir = resolve('../build/WI-20261010-ATS-026-frontend-dist');
const allowed = new Set(['SYSTEMROOT', 'WINDIR', 'TEMP', 'TMP', 'PATH', 'NODE_ENV']);
if (Object.keys(process.env).some(k => !allowed.has(k.toUpperCase()))) {
  console.error('CHILD_ENV_ALLOWLIST_FAILED'); process.exit(2);
}
if (fs.existsSync(outDir)) {
  console.error('OUTPUT_ALREADY_EXISTS'); process.exit(3);
}
const typecheck = spawnSync(process.execPath, ['node_modules/typescript/bin/tsc', '--noEmit'], {
  cwd: process.cwd(), env: process.env, encoding: 'utf8'
});
if (typecheck.status !== 0) {
  console.error('ISOLATED_TYPECHECK_FAILED'); process.exit(4);
}
const warnings = [];
let resolved = {};
try {
  const result = await build({
    configFile: false,
    envDir: false,
    mode: 'production',
    base: '/',
    plugins: [
      react(),
      {
        name: 'wi026-env-free-build-gate',
        enforce: 'post',
        configResolved(config) {
          const names = Object.keys(config.env).sort();
          if (names.some(k => !['BASE_URL', 'DEV', 'MODE', 'PROD', 'SSR'].includes(k)) ||
              config.configFile || config.envDir !== false ||
              !config.isProduction || config.base !== '/' ||
              config.build.outDir !== outDir || config.build.sourcemap !== false) {
            throw new Error('RESOLVED_CONFIG_GATE_FAILED');
          }
          resolved = { envNames: names, configFileDisabled: true, envDirDisabled: true,
            production: config.isProduction, base: config.base, sourceMaps: false };
        }
      }
    ],
    resolve: { alias: { '@': resolve('src') } },
    logLevel: 'silent',
    build: {
      outDir, emptyOutDir: false, sourcemap: false,
      rollupOptions: { onwarn(warning) { warnings.push(warning.code || 'UNCLASSIFIED'); } }
    }
  });
  const bundles = Array.isArray(result) ? result : [result];
  console.log(JSON.stringify({ startedAt, finishedAt: new Date().toISOString(),
    typecheck: 'PASS', build: 'PASS', outputDirectory: 'build/WI-20261010-ATS-026-frontend-dist',
    node: process.version, inheritedEnvironment: 'CLEARED',
    childEnvironmentNames: Object.keys(process.env).sort(), resolved,
    warningCodes: warnings, rollupOutputItems: bundles.reduce((n,b) => n + b.output.length, 0)
  }));
} catch (error) {
  console.error('ISOLATED_BUILD_FAILED');
  process.exitCode = 5;
}
'@
$info=[Diagnostics.ProcessStartInfo]::new()
$info.FileName='C:/Program Files/nodejs/node.exe'
$info.WorkingDirectory=(Join-Path (Get-Location).Path 'frontend')
$info.UseShellExecute=$false
$info.CreateNoWindow=$true
$info.RedirectStandardInput=$true
$info.RedirectStandardOutput=$true
$info.RedirectStandardError=$true
$info.ArgumentList.Add('--input-type=module')
$info.ArgumentList.Add('-')
$info.Environment.Clear()
$info.Environment['SystemRoot']=$env:SystemRoot
$info.Environment['WINDIR']=$env:SystemRoot
$info.Environment['TEMP']=[IO.Path]::GetTempPath()
$info.Environment['TMP']=[IO.Path]::GetTempPath()
$info.Environment['PATH']='C:/Program Files/nodejs;'+(Join-Path $env:SystemRoot 'System32')
$info.Environment['NODE_ENV']='production'
$process=[Diagnostics.Process]::new()
$process.StartInfo=$info
[void]$process.Start()
$out=$process.StandardOutput.ReadToEndAsync()
$err=$process.StandardError.ReadToEndAsync()
$process.StandardInput.Write($script)
$process.StandardInput.Close()
$process.WaitForExit()
$stdout=$out.GetAwaiter().GetResult()
$stderr=$err.GetAwaiter().GetResult()
$exit=$process.ExitCode
$process.Dispose()
if($stdout){Write-Output $stdout}
if($stderr){Write-Output $stderr}
exit $exit

frontendCompletion.exactVerificationPowerShellCommand:
