$badFiles=@($files|Where-Object{$_.Name -match '(?i)^\.env|\.map$|\.sql$|\.pem$|\.key$|\.p12$|\.pfx$|\.jks$|^application.*\.ya?ml$'})
$badText=0
foreach($file in $files|Where-Object{$_.Extension -in @('.html','.js','.css','.json','.svg','.txt')}) {
 $text=Get-Content -LiteralPath $file.FullName -Raw
 if($text -match '(?i)trycloudflare\.com|(?:ngrok-free\.app|ngrok\.io|ngrok-free\.dev)|BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY' -or $text -cmatch '\bVITE_[A-Z0-9_]+\b'){ $badText++ }
}
if($badFiles.Count -or $badText){throw 'FRONTEND_OUTPUT_SAFETY_GATE_FAILED'}
$records=@($files|ForEach-Object{[pscustomobject]@{path=$_.FullName.Substring($root.Length+1).Replace('\','/');bytes=$_.Length;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash}})
$identity=($records|ForEach-Object{$_.path+"`t"+$_.sha256+"`n"}) -join ''
$m=Get-Content deliverables/agent/WI-20261010-ATS-026-artifact.json -Raw|ConvertFrom-Json
foreach($record in @($m.sourceIdentity.files)+@($m.frontend.files)+@($m.frontend.previousDist)) {if((Get-FileHash -LiteralPath $record.path -Algorithm SHA256).Hash -ne $record.sha256){throw 'INPUT_OR_DIST_CHANGED'}}
foreach($record in $m.backend.preservedArtifacts) {if((Get-FileHash -LiteralPath $record.savedPath -Algorithm SHA256).Hash -ne $record.sha256){throw 'SAVED_JAR_CHANGED'}}
if((Get-FileHash -LiteralPath $m.backend.artifact.path -Algorithm SHA256).Hash -ne $m.backend.artifact.sha256){throw 'BACKEND_CHANGED'}
$enum=@(git ls-files --cached --others --exclude-standard -- frontend | Where-Object { $_ -notmatch '(^|/)(node_modules|dist|coverage)/|(^|/)\.env($|\.)' -or $_ -eq 'frontend/.env.example' } | Sort-Object -Unique)
if(@(Compare-Object $enum @($m.frontend.files.path|Sort-Object -Unique)).Count){throw 'FRONTEND_INPUT_SET_CHANGED'}
$links=@(Get-ChildItem -LiteralPath $out -Recurse -Attributes ReparsePoint)
if($links.Count){throw 'OUTPUT_REPARSE_POINT_FOUND'}
[pscustomobject]@{verifiedAt=(Get-Date).ToString('o');outputPath=$relative;files=$records;fileCount=$records.Count;bytes=($records|Measure-Object bytes -Sum).Sum;outputSetSha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($identity)));prohibitedFilenameCount=$badFiles.Count;prohibitedTextMatchFileCount=$badText;reparsePointCount=$links.Count;sourceInputsUnchanged=974;previousDistFilesUnchanged=143;backendAndSavedJarsUnchanged=$true;head=(git rev-parse HEAD);branch=(git branch --show-current);handoffSha256=(Get-FileHash deliverables/agent/WI-20261010-ATS-026-handoff.md -Algorithm SHA256).Hash;largestFiles=@($records|Sort-Object bytes -Descending|Select-Object -First 3)}|ConvertTo-Json -Depth 5
